// 아래 함수는 그대로 두세요. 검사기가 부릅니다
function applyRule(kind, price) {
  const rule = chooseRule(kind);

  if (typeof rule !== 'function') {
    return 'chooseRule 이 함수를 돌려주지 않았습니다';
  }

  return rule(price);
}

function chooseRule(kind) {
  const half = function (price) {
    return price / 2;
  };

  const thousandOff = function (price) {
    return price - 1000;
  };

  const keep = function (price) {
    return price;
  };

  if (kind === 'half') {
    return half;
  }

  if (kind === 'thousandOff') {
    return thousandOff;
  }

  return keep;
}
